// Extract file information from webhook payload
const fileData = $input.first().json;

// Get file details
const fileName = fileData.name || fileData.fileName || 'Unknown File';
const fileId = fileData.id || fileData.fileId || '';
const createdTime = fileData.createdTime || fileData.created_time || new Date().toISOString();
const fileSize = fileData.size || fileData.fileSize || 'N/A';
const mimeType = fileData.mimeType || fileData.mime_type || 'N/A';
const fileUrl = fileData.webViewLink || fileData.web_view_link || fileData.url || '';

// Get file content (if provided)
const fileContent = fileData.content || fileData.fileContent || fileData.textContent || '';
const contentPreview = fileContent ? 
  (fileContent.length > 500 ? fileContent.substring(0, 500) + '...' : fileContent) : 
  'No content available';

// Format email content
const emailSubject = `📄 New File Created: ${fileName}`;
const emailBody = `
<!DOCTYPE html>
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
    .container { max-width: 600px; margin: 0 auto; padding: 20px; }
    .header { background-color: #4285f4; color: white; padding: 20px; border-radius: 5px 5px 0 0; }
    .content { background-color: #f9f9f9; padding: 20px; border-radius: 0 0 5px 5px; }
    .info-row { margin: 10px 0; }
    .label { font-weight: bold; color: #555; }
    .value { color: #333; }
    .content-preview { background-color: white; padding: 15px; border-left: 4px solid #4285f4; margin-top: 15px; white-space: pre-wrap; font-family: monospace; }
    .button { display: inline-block; padding: 10px 20px; background-color: #4285f4; color: white; text-decoration: none; border-radius: 5px; margin-top: 15px; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h2>📄 New File Created in Google Drive</h2>
    </div>
    <div class="content">
      <div class="info-row">
        <span class="label">File Name:</span>
        <span class="value">${fileName}</span>
      </div>
      <div class="info-row">
        <span class="label">Created Time:</span>
        <span class="value">${new Date(createdTime).toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh', dateStyle: 'full', timeStyle: 'long' })}</span>
      </div>
      <div class="info-row">
        <span class="label">File Size:</span>
        <span class="value">${fileSize}</span>
      </div>
      <div class="info-row">
        <span class="label">File Type:</span>
        <span class="value">${mimeType}</span>
      </div>
      ${fileUrl ? `<div class="info-row">
        <a href="${fileUrl}" class="button">Open File in Drive</a>
      </div>` : ''}
      <div class="content-preview">
        <strong>File Content Preview:</strong><br/><br/>
        ${contentPreview}
      </div>
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    emailSubject,
    emailBody,
    fileName,
    fileId,
    createdTime,
    fileSize,
    mimeType,
    fileUrl,
    contentPreview
  }
}];
